<script setup>
import { computed, ref } from 'vue'
import { ROUND_TYPES } from '@/data/battingRounds'
import { CAGE_DRILLS, CAGE_SKILL_ORDER } from '@/data/cageDrills'
import { targetStyle, roundLabel } from '@/utils/scriptedPractice'
const props = defineProps({ modelValue: {type:Array,default:()=>[]}, type:String, disabled:Boolean })
const emit=defineEmits(['update:modelValue'])
const pitch=ref('FB'), coord=ref(0), skill=ref(CAGE_SKILL_ORDER[0]), swings=ref(10)
const drills=computed(()=>CAGE_DRILLS.filter(d=>d.skill===skill.value))
function update(plan) { if (!props.disabled) emit('update:modelValue',plan) }
function add(item) { update([...props.modelValue,item]) }
function remove(index) { update(props.modelValue.filter((_,i)=>i!==index)) }
function move(index,delta) { const next=index+delta; if(next<0||next>=props.modelValue.length)return;const list=[...props.modelValue];[list[index],list[next]]=[list[next],list[index]];update(list) }
function tap(e) { if(props.disabled)return;const r=e.currentTarget.getBoundingClientRect();coord.value=Math.min(59,Math.max(0,Math.floor((e.clientY-r.top)/r.height*60)))*60+Math.min(59,Math.max(0,Math.floor((e.clientX-r.left)/r.width*60)))+1 }
function arrow(e) { const d={ArrowLeft:-1,ArrowRight:1,ArrowUp:-60,ArrowDown:60}[e.key];if(!d||props.disabled)return;e.preventDefault();coord.value=Math.max(1,Math.min(3600,(coord.value||1830)+d)) }
function setCount(index,value) { update(props.modelValue.map((r,i)=>i===index?{...r,swing_count:Number(value)}:r)) }
function addDrill(d) { add({drillId:d.id,drillLabel:d.name,skill:d.skill,objective:d.objective,coachingCues:d.coachingCues,swing_count:Number(swings.value)}) }
</script>
<template><section class="script-builder"><h2>{{ type === 'P' ? 'Build your pitch sequence' : type === 'B' ? 'Build your batting rounds' : 'Cage practice setup' }}</h2>
 <template v-if="type === 'P'"><p>Select a pitch and tap its intended location. Every pitcher follows this sequence.</p><div class="target" role="button" tabindex="0" aria-label="Select intended pitch location using tap or arrow keys" @click="tap" @keydown="arrow"><div class="zone" /><span v-if="coord" class="cross" :style="targetStyle(coord)">+</span></div><div class="choices"><button v-for="p in ['FB','CH','SL','CV','OTHER']" :key="p" type="button" :disabled="disabled" :aria-pressed="pitch===p" @click="pitch=p">{{ p }}</button></div><button type="button" :disabled="disabled || !coord" @click="add({pitchType:pitch,intendedCoord:coord})">+ Add pitch</button></template>
 <div v-else-if="type === 'B'" class="round-library"><button v-for="round in ROUND_TYPES" :key="round.id" type="button" :aria-pressed="modelValue.some(r=>r.round_type===round.id)" :disabled="disabled || modelValue.some(r=>r.round_type===round.id)" @click="add({round_type:round.id,swing_count:5})"><strong>{{ round.label }}</strong><small>{{ round.goal }}</small></button></div>
 <template v-else><label>Skill focus<select v-model="skill" :disabled="disabled"><option v-for="s in CAGE_SKILL_ORDER" :key="s">{{ s }}</option></select></label><label>Swings per new round<input v-model.number="swings" type="number" min="1" max="50" :disabled="disabled" /></label><div class="round-library"><button v-for="drill in drills" :key="drill.id" type="button" :disabled="disabled" @click="addDrill(drill)"><strong>{{ drill.name }}</strong><small>Difficulty {{ drill.difficulty }}/5 · {{ drill.equipment }}</small><small>{{ drill.objective }}</small><small>{{ drill.coachingCues }}</small><span>+ Add round</span></button></div></template>
 <ol><li v-for="(item,index) in modelValue" :key="index"><span>{{ index+1 }}. {{ type==='P' ? `${item.pitchType} · target ${item.intendedCoord}` : type==='B' ? roundLabel(item.round_type) : item.drillLabel }}</span><label v-if="type!=='P'">Swings<input :value="item.swing_count" type="number" min="1" :max="type==='B'?20:50" :disabled="disabled" @input="setCount(index,$event.target.value)" /></label><button type="button" :disabled="disabled || index===0" aria-label="Move earlier" @click="move(index,-1)">↑</button><button type="button" :disabled="disabled || index===modelValue.length-1" aria-label="Move later" @click="move(index,1)">↓</button><button type="button" :disabled="disabled" aria-label="Remove step" @click="remove(index)">×</button></li></ol><p v-if="!modelValue.length">Add at least one {{ type==='P'?'pitch':'round' }} to create this practice.</p></section></template>
<style scoped>.script-builder{background:#171d30;border:1px solid #596078;padding:20px;border-radius:22px;margin:20px 0;color:white}h2{font-size:22px;font-weight:800}p{margin:10px 0;color:#d2d7e5}button{min-height:44px;padding:10px 14px;border:1px solid #68728b;border-radius:14px;background:#282f44;color:white}button[aria-pressed=true]{background:#ff2451}button:disabled{opacity:.45}button:focus-visible,.target:focus-visible{outline:3px solid #8fe7ff}.choices{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.target{position:relative;width:min(100%,300px);aspect-ratio:1;background:url('../../assets/img/training/batting-catcher.png') center/100% 100%;cursor:crosshair;margin:14px auto}.zone{position:absolute;left:25%;top:23.333%;width:50%;height:51.667%;border:2px solid white;background:#ffffff30}.cross{position:absolute;transform:translate(-50%,-50%);font-size:36px;color:#8fffee;font-weight:900}.round-library{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px;max-height:400px;overflow:auto;margin:14px 0}.round-library button{text-align:left}.round-library small{display:block;color:#cad1e0;margin:5px 0}li{display:flex;gap:8px;align-items:center;margin:10px 0;flex-wrap:wrap}li>span{flex:1;min-width:120px}input,select{background:#0d1323;color:white;padding:8px;border:1px solid #7b849c;border-radius:8px;margin:5px}input{width:70px}label{display:inline-block}</style>
